	@Test
	void mapFullWhileFencingThePlanGrowsBeforeAnyStatementRewrite(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path referenceDirectory = evidence.resolve("reference");
		Path targetDirectory = evidence.resolve("target");
		createFixture(referenceDirectory);
		createFixture(targetDirectory);
		LmdbCompatibilityFixtures.nativePut(targetDirectory, "ref_counts", new byte[] { 0 }, new byte[] { 1 });
		CapturedStore reference = new CapturedStore(referenceDirectory);
		List<String> explicit;
		List<String> all;
		try {
			reference.init();
			explicit = statements(reference, false);
			all = statements(reference, true);
		} finally {
			reference.shutDown();
		}
		CapturedStore target = new CapturedStore(targetDirectory);
		AtomicBoolean injected = new AtomicBoolean();
		AtomicBoolean rewritesStarted = new AtomicBoolean();
		AtomicLong mapBeforeFailure = new AtomicLong();
		LmdbLanguageTagVariantMerge.stepObserverForTesting = step -> {
			if (step == LmdbLanguageTagVariantMerge.Step.STATEMENT_BATCH_COMMITTED) {
				rewritesStarted.set(true);
			}
		};
		SailException openFailure = null;
		try {
			try (MockedStatic<LMDB> ignored = mockStatic(LMDB.class, invocation -> {
				if (invocation.getMethod().getName().equals("mdb_put")
						&& hasFrame("planLanguageTagVariantMerge") && hasFrame("writeReferenceCountProof")
						&& injected.compareAndSet(false, true)) {
					assertTrue(!rewritesStarted.get(), "the fence must fail before any statement rewrite");
					mapBeforeFailure.set(target.values.mapSizeBytes());
					return LMDB.MDB_MAP_FULL;
				}
				return CALLS_REAL_METHODS.answer(invocation);
			})) {
				try {
					target.init();
				} catch (SailException failure) {
					openFailure = failure;
				}
			}
			assertTrue(injected.get(), "native capacity must fail while persisting the recognized marker fence");
			assertNull(openFailure, "the plan fence must grow and retry before any statement rewrite");
			assertTrue(target.values.mapSizeBytes() > mapBeforeFailure.get(), "the actual dictionary map must grow");
			assertTrue(rewritesStarted.get(), "the retried plan must perform the actual statement rewrite");
			assertEquals(explicit, statements(target, false));
			assertEquals(all, statements(target, true));
		} finally {
			LmdbLanguageTagVariantMerge.stepObserverForTesting = null;
			target.shutDown();
		}
		assertNull(LmdbCompatibilityFixtures.nativeGet(targetDirectory, "ref_counts", new byte[] { 0 }),
				"a completed untrusted alias migration must fence the historical marker");
	}

	private static boolean hasFrame(String method) {
		for (StackTraceElement frame : Thread.currentThread().getStackTrace()) {
			if (frame.getClassName().equals(ValueStore.class.getName()) && frame.getMethodName().equals(method)) {
				return true;
			}
		}
		return false;
	}

	private static boolean inLosingLiteralRetirement() {
		for (StackTraceElement frame : Thread.currentThread().getStackTrace()) {
			if (frame.getClassName().equals(ValueStore.class.getName())
					&& frame.getMethodName().equals("retireLosingLiterals")) {
				return true;
			}
		}
		return false;
	}

	private static void createFixture(Path directory) throws IOException {
		LmdbCompatibilityFixtures.extract("v2-610-language-aliases.zip", directory);
		Properties properties = new Properties();
		properties.setProperty("version", "2");
		properties.setProperty("triple-indexes", "spoc,posc,ospc");
		properties.setProperty("triple-term-indexes", "spoc,cspo");
		try (var output = Files.newOutputStream(directory.resolve("store.properties"))) {
			properties.store(output, null);
		}
	}

	private static List<String> statements(LmdbStore store, boolean includeInferred) {
		List<String> rows = new ArrayList<>();
		try (SailConnection connection = store.getConnection();
				var statements = connection.getStatements(null, null, null, includeInferred)) {
			while (statements.hasNext()) {
				Statement statement = statements.next();
				rows.add(NTriplesUtil.toNTriplesString(statement.getSubject()) + " "
						+ NTriplesUtil.toNTriplesString(statement.getPredicate()) + " "
						+ NTriplesUtil.toNTriplesString(statement.getObject())
						+ (statement.getContext() == null ? "" : " "
								+ NTriplesUtil.toNTriplesString(statement.getContext())));
			}
		}
		Collections.sort(rows);
		return rows;
	}

	private static final class CapturedStore extends LmdbStore {
		private volatile ValueStore values;

		private CapturedStore(Path directory) {
			super(directory.toFile(), new LmdbStoreConfig("spoc,posc,ospc").setTripleTermIndexes("spoc,cspo")
					.setAutoGrow(true).setSketchEstimatorEnabled(false).setPredicateGuaranteeIndexEnabled(false));
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			LmdbSailStore.ValueStoreFactory factory = (path, stored, selected) -> {
				ValueStore created = new ValueStore(path, stored, selected, false, null,
						LmdbStoreFormat.fromProperties(stored, selected), true);
				values = created;
				return created;
			};
			return new LmdbSailStore(directory, properties, config, sketches, factory,
					(path, stored, selected, values) -> new TripleStore(path, stored, selected, values));
		}
	}
